      nearFullLibrary.querySelector('[data-media-show-selected]').click();
      nearFullLibrary.querySelector('.media-selection-review [data-media-select]').click();
      assert(selectionLimitNote.textContent === 'Albums can contain up to 50 photos.' && nearFullLibrary.querySelector('.media-browser-selection p').textContent === '0 photos selected' && nearFullLibrary.querySelector('[data-media-add-selected]').disabled, 'Deselecting a photo must clear the limit message and reset the Add action.');
      assert(nearFullLibrary.querySelector('.media-selection-review').hidden && !nearFullLibrary.querySelector('[data-media-results]').hidden && document.activeElement === available && nearFullLibrary.querySelector('[data-media-show-selected]').hidden, 'Deselecting the final photo at capacity must automatically restore its library page and focus.');
